mapper.select:
SELECT id, task_id, document_id, field_id, field_code, field_name, field_value, original_value, manual_value, final_value, raw_text, page_no, confidence, result_status, is_modified, create_time, update_time
FROM extract_result
WHERE id = #{id}

SELECT r.id, r.task_id, r.document_id, r.field_id, r.field_code, r.field_name, r.field_value, r.original_value, r.manual_value, r.final_value, r.raw_text, r.page_no, r.confidence, r.result_status, r.is_modified, r.create_time, r.update_time
FROM extract_result r
INNER JOIN extract_task t ON t.id = r.task_id
WHERE r.id = #{id}
  AND t.created_by = #{userId}
